ALTER TABLE GRADUATORIET_COM ADD LISTA_FIRMATARI VARCHAR(200);

CREATE OR REPLACE ALGORITHM=MERGE VIEW VW_SCADENZARIO AS SELECT VW_BATCH_SCADENZARIO.IDCOMUNE AS IDCOMUNE, VW_BATCH_SCADENZARIO.ID AS CODICESCADENZA, VW_BATCH_SCADENZARIO.SOFTWARE AS SOFTWARE, VW_BATCH_SCADENZARIO.CODICEISTANZA AS CODICEISTANZA, ISTANZE.NUMEROPROTOCOLLO AS NUMEROPROTOCOLLO, ISTANZE.DATAPROTOCOLLO AS DATAPROTOCOLLO, ISTANZE.NUMEROISTANZA AS NUMEROISTANZA, ISTANZE.CHIUSURA AS CODSTATOISTANZA, STATIISTANZA.STATO AS DESCRSTATOISTANZA, VW_BATCH_SCADENZARIO.CODICEMOVIMENTO AS CODMOVIMENTO, VW_BATCH_SCADENZARIO.DESCRMOVIMENTO AS DESCRMOVIMENTO, DATE_FORMAT(MOVIMENTI.DATA,'%d/%m/%Y') AS DATAMOVIMENTO, VW_BATCH_SCADENZARIO.TIPOMOVIMENTODAFARE AS CODMOVIMENTODAFARE, VW_BATCH_SCADENZARIO.DESCRMOVIMENTODAFARE AS DESCRMOVIMENTODAFARE, DATE_FORMAT(VW_BATCH_SCADENZARIO.DATASCADENZA,'%d/%m/%Y') AS DATASCADENZASTR, VW_BATCH_SCADENZARIO.CODICEINVENTARIO AS CODICEINVENTARIO, VW_BATCH_SCADENZARIO.CODICEAMMINISTRAZIONE AS CODICEAMMINISTRAZIONE, RESPONSABILI.RESPONSABILE AS RESPONSABILE, INVENTARIOPROCEDIMENTI.PROCEDIMENTO AS PROCEDIMENTO, TIPIPROCEDURE.PROCEDURA AS PROCEDURA, SOFTWARE.DESCRIZIONE AS MODULOSOFTWARE, AMMINISTRAZIONI.AMMINISTRAZIONE AS AMM_AMMINISTRAZIONE, AMMINISTRAZIONI.PARTITAIVA AS AMM_PARTITAIVA, AMMINISTRAZIONI.PASSWORD AS AMM_PASSWORD, CONCAT_WS(' ',ANAGRAFE.NOMINATIVO,ANAGRAFE.NOME) AS RIC_NOMINATIVO, IFNULL(ANAGRAFE.CODICEFISCALE,'') AS RIC_CODICEFISCALE, IFNULL(ANAGRAFE.PARTITAIVA,'') AS RIC_PARTITAIVA, ANAGRAFE.INDIRIZZO AS RIC_INDIRIZZO, ANAGRAFE.CAP AS RIC_CAP, ANAGRAFE.CITTA AS RIC_LOCALITA, COMUNERESIDENZA.COMUNE AS RIC_CITTA, COMUNERESIDENZA.PROVINCIA AS RIC_PROVINCIA, ANAGRAFE.PASSWORD AS RIC_PASSWORD, CONCAT_WS(' ',TECNICO.NOMINATIVO,TECNICO.NOME) AS TEC_NOMINATIVO, IFNULL(TECNICO.CODICEFISCALE,'') AS TEC_CODICEFISCALE, IFNULL(TECNICO.PARTITAIVA,'') AS TEC_PARTITAIVA, TECNICO.PASSWORD AS TEC_PASSWORD, CONCAT_WS(' ',AZIENDA.NOMINATIVO,AZIENDA.NOME) AS AZ_NOMINATIVO, IFNULL(AZIENDA.CODICEFISCALE,'') AS AZ_CODICEFISCALE, IFNULL(AZIENDA.PARTITAIVA,'') AS AZ_PARTITAIVA, AZIENDA.PASSWORD AS AZ_PASSWORD, TIPIMOVIMENTO.FK_FO_SOGGETTIESTERNI AS FK_FO_SOGGETTIESTERNI FROM VW_BATCH_SCADENZARIO INNER JOIN ISTANZE ON ISTANZE.IDCOMUNE = VW_BATCH_SCADENZARIO.IDCOMUNE AND ISTANZE.CODICEISTANZA = VW_BATCH_SCADENZARIO.CODICEISTANZA INNER JOIN RESPONSABILI ON RESPONSABILI.IDCOMUNE = ISTANZE.IDCOMUNE AND RESPONSABILI.CODICERESPONSABILE = ISTANZE.CODICERESPONSABILE INNER JOIN MOVIMENTI ON MOVIMENTI.IDCOMUNE = VW_BATCH_SCADENZARIO.IDCOMUNE AND MOVIMENTI.CODICEMOVIMENTO = VW_BATCH_SCADENZARIO.CODICEMOVIMENTO INNER JOIN TIPIMOVIMENTO ON TIPIMOVIMENTO.IDCOMUNE = VW_BATCH_SCADENZARIO.IDCOMUNE AND TIPIMOVIMENTO.TIPOMOVIMENTO = VW_BATCH_SCADENZARIO.TIPOMOVIMENTODAFARE INNER JOIN TIPIPROCEDURE ON TIPIPROCEDURE.IDCOMUNE = ISTANZE.IDCOMUNE AND TIPIPROCEDURE.CODICEPROCEDURA = ISTANZE.CODICEPROCEDURA INNER JOIN SOFTWARE ON SOFTWARE.CODICE = VW_BATCH_SCADENZARIO.SOFTWARE INNER JOIN ANAGRAFE ON ANAGRAFE.IDCOMUNE = ISTANZE.IDCOMUNE AND ANAGRAFE.CODICEANAGRAFE = ISTANZE.CODICERICHIEDENTE INNER JOIN STATIISTANZA ON STATIISTANZA.IDCOMUNE = ISTANZE.IDCOMUNE AND STATIISTANZA.SOFTWARE = ISTANZE.SOFTWARE AND STATIISTANZA.CODICESTATO = ISTANZE.CHIUSURA LEFT JOIN AMMINISTRAZIONI ON AMMINISTRAZIONI.IDCOMUNE = VW_BATCH_SCADENZARIO.IDCOMUNE AND AMMINISTRAZIONI.CODICEAMMINISTRAZIONE = VW_BATCH_SCADENZARIO.CODICEAMMINISTRAZIONE LEFT JOIN INVENTARIOPROCEDIMENTI ON INVENTARIOPROCEDIMENTI.IDCOMUNE = VW_BATCH_SCADENZARIO.IDCOMUNE AND INVENTARIOPROCEDIMENTI.CODICEINVENTARIO = VW_BATCH_SCADENZARIO.CODICEINVENTARIO LEFT JOIN COMUNI COMUNERESIDENZA ON COMUNERESIDENZA.CODICECOMUNE = ANAGRAFE.COMUNERESIDENZA LEFT JOIN ANAGRAFE TECNICO ON TECNICO.IDCOMUNE = ISTANZE.IDCOMUNE AND TECNICO.CODICEANAGRAFE = ISTANZE.CODICEPROFESSIONISTA LEFT JOIN ANAGRAFE AZIENDA ON AZIENDA.IDCOMUNE = ISTANZE.IDCOMUNE AND AZIENDA.CODICEANAGRAFE = ISTANZE.CODICETITOLARELEGALE;


