(
  IDCOMUNE VARCHAR(6) NOT NULL 
, FLUSSO VARCHAR(1) NOT NULL 
, CODICESEQUENZA VARCHAR(50) NOT NULL 
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

ALTER TABLE PROTOCOLLO_SEQUENZE ADD CONSTRAINT PROTOCOLLO_SEQUENZE_PK PRIMARY KEY(IDCOMUNE,FLUSSO);

